function baseAnchors(properties,review){
 const stored=Array.isArray(review?.anchors)&&review.anchors.length?review.anchors:Array.isArray(properties.directionAnchors)&&properties.directionAnchors.length?properties.directionAnchors:[{id:'primary',name:'Primær kystdel',dataPoint:properties.dataPoint,pinPoint:properties.pinPoint,onshoreDirectionDeg:properties.onshoreDirectionDeg,weight:1}];
 return stored.map((a,i)=>({id:String(a.id||`anchor-${i+1}`),name:String(a.name||`Kystdel ${i+1}`),dataPoint:Array.isArray(a.dataPoint)?a.dataPoint.map(Number):null,pinPoint:Array.isArray(a.pinPoint)?a.pinPoint.map(Number):null,onshoreDirectionDeg:normalizeDeg(a.onshoreDirectionDeg??(a.dataPoint&&a.pinPoint?bearingDeg(a.dataPoint,a.pinPoint):0)),weight:Number.isFinite(Number(a.weight))?Math.max(.1,Number(a.weight)):1,verified:Boolean(a.verified)}));
}
function arrowEnd(anchor){return anchor.dataPoint?destinationPoint(anchor.dataPoint,anchor.onshoreDirectionDeg,4):null;}
function drawDirectionZone(feature,anchors,selectedAnchorId,onPointMoved){
 if(!window.L)return;const p=feature.properties||{};clearDirectionLayers();
 const coords=[];const collect=x=>{if(Array.isArray(x)&&typeof x[0]==='number'&&typeof x[1]==='number')coords.push([x[1],x[0]]);else if(Array.isArray(x))x.forEach(collect)};collect(feature.geometry?.coordinates||[]);
 if(coords.length)addDirectionLayer(L.polygon(coords,{color:'#d8a232',weight:4,fillOpacity:.06,interactive:false}));
 if(Array.isArray(p.coastLine)&&p.coastLine.length)addDirectionLayer(L.polyline(p.coastLine.map(x=>[x[1],x[0]]),{color:'#5ee093',weight:5,interactive:false}));
 anchors.forEach((anchor,index)=>{
  const selected=anchor.id===selectedAnchorId;const suffix=anchors.length>1?` · ${anchor.name}`:'';
  if(anchor.dataPoint){const marker=addDirectionLayer(L.marker([anchor.dataPoint[1],anchor.dataPoint[0]],{draggable:true,title:`Marint datapunkt${suffix}`,icon:L.divIcon({className:'direction-point-icon',html:`<span class="direction-point sea ${selected?'selected':''}">${index+1}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).bindTooltip(`Blåt punkt: marint datapunkt${suffix}`));marker.on('dragend',e=>{const ll=e.target.getLatLng();onPointMoved(anchor.id,'dataPoint',[ll.lng,ll.lat]);});}
  if(anchor.pinPoint){const marker=addDirectionLayer(L.marker([anchor.pinPoint[1],anchor.pinPoint[0]],{draggable:true,title:`Strand-/landpunkt${suffix}`,icon:L.divIcon({className:'direction-point-icon',html:`<span class="direction-point land ${selected?'selected':''}">${index+1}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).bindTooltip(`Grønt punkt: strand-/landpunkt${suffix}`));marker.on('dragend',e=>{const ll=e.target.getLatLng();onPointMoved(anchor.id,'pinPoint',[ll.lng,ll.lat]);});}
  const end=arrowEnd(anchor);if(anchor.dataPoint&&end){addDirectionLayer(L.polyline([[anchor.dataPoint[1],anchor.dataPoint[0]],[end[1],end[0]]],{color:selected?'#ff4f4f':'#ff8d8d',weight:selected?7:4,opacity:selected?1:.7,interactive:false}));addDirectionLayer(L.circleMarker([end[1],end[0]],{radius:selected?6:4,color:'#ff4f4f',fillColor:'#ff4f4f',fillOpacity:1,interactive:false}).bindTooltip(`Retningen peger hertil: ${directionLabel(anchor.onshoreDirectionDeg)}${suffix}`));}
 });
 const bounds=directionLayers.flatMap(x=>x.getBounds?[x.getBounds()]:[]).reduce((a,b)=>a?a.extend(b):b,null);if(bounds?.isValid()&&!directionMap.__hasFit){directionMap.fitBounds(bounds.pad(.3));directionMap.__hasFit=true;}
}

