function renderObservations(){
 const obs=JSON.parse(localStorage.getItem('ravradar-observations-v2')||'[]');
 const finds=obs.filter(x=>x.found===true||['small','medium','good'].includes(x.result)).length;
 const active=activePublicRavScoreState();
 const exportCard=active.ok
  ? `<article class="admin-card"><h2>Eksport og databeskyttelse</h2><p>Eksporten er en fast allowlist uden bruger-id, GPS, rute eller råt vejrsnapshot. Hver række klassificeres mod den verificerede aktive binding for ${esc(active.value.labelDa)}; eksportens topniveau bærer samme eksakte binding.</p><button id="exportObs" class="admin-button">Eksportér dataminimeret JSON</button></article>`
  : activeModelUnavailableCard(active,{title:'Observationseksport blokeret'});
 content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Observationer</h2><div class="metric">${obs.length}</div></article><article class="admin-card"><h2>Registrerede fund</h2><div class="metric">${finds}</div></article><article class="admin-card"><h2>Bundne snapshots</h2><div class="metric">${obs.filter(x=>x.forecast_snapshot_id).length}</div><p class="muted">Eksporteres kun som sikker snapshotreference</p></article></div>${exportCard}`;
 if(!active.ok)return;
 document.querySelector('#exportObs').onclick=()=>{
  const rows=obs.map(row=>activeAdminObservationDto(row,active.value));
  download('ravradar-observationer.json',{
   schemaVersion:2,
   exportedAt:new Date().toISOString(),
   privacyProfile:'trip-admin-safe-dto-v2',
   activePublicModel:{
    ...active.value.binding,
    activeModelKind:active.value.kind,
    activationState:active.value.scoreProfile.activationState,
    observationCalibrationEligible:active.value.observationCalibrationEligible,
   },
   rows,
  });
 };
}

async function renderUsers(){
 const canManageAll=state.access?.profile?.role==='owner'||state.access?.permissions?.has('full_admin');
 const manageablePermissions=canManageAll?PERMISSIONS:EXPERT_PERMISSIONS;
 content.innerHTML=`<article class="admin-card"><h2>Eksperter og rettigheder</h2><p class="muted">${canManageAll?'Administratorer kan tildele alle dokumenterede rettigheder.':'Du kan kun tildele de tre sikre ekspertadgange: administration, håndbog og faglig gennemgang.'}</p><div id="profilesList" class="admin-grid"><p class="muted">Henter brugere…</p></div></article>`;
 const host=document.querySelector('#profilesList');
 try{state.profiles=await listProfiles();const visibleProfiles=canManageAll?state.profiles:state.profiles.filter(profile=>profile.role==='expert');if(!visibleProfiles.length){host.innerHTML='<div class="empty">Ingen ekspertprofiler blev fundet.</div>';return;}
 host.innerHTML=visibleProfiles.map(profile=>{const active=new Set((profile.user_permissions||[]).filter(x=>x.enabled).map(x=>x.permission_key));return `<article class="admin-card permission-card" data-user-id="${esc(profile.id)}"><div class="rule-card-head"><div><h3>${esc(profile.display_name||profile.email)}</h3><p class="muted">${esc(profile.email||'')} · ${esc(profile.role||'expert')}</p></div><span class="badge ${profile.is_active!==false?'active':'draft'}">${profile.is_active!==false?'Aktiv':'Deaktiveret'}</span></div><div class="permission-list">${manageablePermissions.map(p=>`<label class="permission-option"><input type="checkbox" name="${esc(p.id)}" ${active.has(p.id)||profile.role==='owner'?'checked':''} ${profile.role==='owner'?'disabled':''}><span>${esc(p.label)}</span></label>`).join('')}</div>${profile.role==='owner'?'<p class="hint">Owner har altid alle rettigheder.</p>':'<button class="admin-button save-user-permissions" type="button">Gem rettigheder</button><p class="form-status"></p>'}</article>`}).join('');
 host.querySelectorAll('.save-user-permissions').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-user-id]');const status=card.querySelector('.form-status');const values={};manageablePermissions.forEach(p=>values[p.id]=card.querySelector(`[name="${p.id}"]`).checked);button.disabled=true;status.textContent='Gemmer…';try{await savePermissions(card.dataset.userId,values);status.textContent='Rettighederne er gemt og gælder med det samme.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
 }catch(error){host.innerHTML=`<div class="empty">${esc(error.message)}</div>`;}
}

async function renderHandbook(){
 content.innerHTML='<article class="admin-card"><h2>Håndbog</h2><p>Henter håndbog, reviewkø og lokale nødkladder…</p></article>';
 try{
  const [book,reviews]=await Promise.all([loadAdminDocument('handbook',null),listHandbookReviews().catch(error=>({error:error.message,rows:[]}))]);
  if(!book)throw new Error('Håndbogen er ikke installeret i Supabase.');
  const canReview=allowed('handbook_review'),canManage=state.access?.profile?.role==='owner'||state.access?.permissions?.has('full_admin');
  const reviewRows=Array.isArray(reviews)?reviews:(reviews.rows||[]),reviewError=Array.isArray(reviews)?null:reviews.error;
  const localDrafts=listLocalHandbookDrafts();
  const statusLabel=x=>({new:'Ny',reviewing:'Under vurdering',accepted:'Accepteret',implemented:'Implementeret',rejected:'Afvist',archived:'Slettet'})[x]||x||'Ny';
  const reviewCards=reviewRows.length?reviewRows.map(row=>`<article class="admin-card handbook-review-card" data-review-id="${esc(row.id)}"><div class="rule-card-head"><div><span class="badge ${row.status==='new'?'draft':row.status==='implemented'?'active':''}">${esc(statusLabel(row.status))}</span><h3>${esc(row.section_title||row.section_id||'Ukendt afsnit')}</h3></div><small>${row.created_at?new Date(row.created_at).toLocaleString('da-DK'):'—'}</small></div><p><b>Problem:</b> ${esc(row.issue||'—')}</p><p><b>Forslag:</b> ${esc(row.proposal||'—')}</p><details><summary>Faglig begrundelse og metadata</summary><p>${esc(row.reasoning||'—')}</p><p class="hint">${esc(row.expertise||'')} · ${esc(row.expert_name||row.client_payload?.expertName||'Ukendt afsender')} ${row.organization||row.client_payload?.organization?'· '+esc(row.organization||row.client_payload?.organization):''}</p></details>${canManage?`<div class="toolbar"><select class="review-status"><option value="new" ${row.status==='new'?'selected':''}>Ny</option><option value="reviewing" ${row.status==='reviewing'?'selected':''}>Under vurdering</option><option value="accepted" ${row.status==='accepted'?'selected':''}>Accepteret</option><option value="rejected" ${row.status==='rejected'?'selected':''}>Afvist</option></select><button class="admin-button secondary save-review-status">Gem status</button><button class="admin-button implement-review">Åbn implementering</button><button class="admin-button danger archive-review">Slet fra køen</button></div><div class="review-implementation" hidden><p class="hint">Redigér hele håndbogsafsnittet. Forslaget er indsat nederst som kladde. Først når du gemmer, ændres den centrale håndbog og reviewet markeres som implementeret.</p><textarea class="implementation-body" rows="14"></textarea><label>Notat om gennemførelsen<input class="implementation-note" value="Forslaget er indarbejdet og kontrolleret af ejer."></label><div class="toolbar"><button class="admin-button save-implementation">Gem i håndbogen</button><button class="admin-button secondary cancel-implementation">Annullér</button></div><p class="form-status"></p></div>`:''}</article>`).join(''):'<div class="empty">Reviewkøen er tom.</div>';
  const localCards=localDrafts.length?localDrafts.map(row=>`<article class="admin-card local-handbook-draft" data-local-review-id="${esc(row.id)}"><h3>${esc(row.sectionTitle||row.sectionId)}</h3><p><b>Problem:</b> ${esc(row.issue)}</p><p><b>Forslag:</b> ${esc(row.proposal)}</p><p class="status-warning">Kun gemt på denne enhed: ${esc(row.lastError||'Central lagring mislykkedes.')}</p><div class="toolbar"><button class="admin-button retry-local-review">Send igen til Supabase</button><button class="admin-button danger delete-local-review">Slet lokal kladde</button></div><p class="form-status"></p></article>`).join(''):'<div class="empty">Ingen lokale nødkladder.</div>';
  content.innerHTML=`<article class="admin-card"><span class="eyebrow">Beskyttet projektviden</span><div class="rule-card-head"><div><h2>${esc(book.title||'RavRadar-håndbogen')}</h2><p>Version ${esc(book.handbookVersion||'ukendt')} · ${esc(book.updatedAt||'')}</p></div><div class="toolbar"><button class="admin-button secondary" id="jumpReviewQueue">Reviewkø (${reviewRows.filter(x=>x.status==='new'||x.status==='reviewing').length})</button><button class="admin-button secondary" id="jumpLocalDrafts">Nødkladder (${localDrafts.length})</button></div></div><div class="status-banner ${canReview?'ok':'warning'}"><strong>${canReview?'Ekspertreview er aktivt':'Kun læseadgang'}</strong><p>${canReview?'Rettelser gemmes centralt og kan straks findes i reviewkøen nederst på denne fane.':'Din konto mangler rettigheden “Indsend faglige rettelser til håndbogen”.'}</p></div>${(book.sections||[]).map(x=>`<section class="handbook-admin-section" data-handbook-section="${esc(x.id)}"><h3>${esc(x.title)}</h3><p>${esc(x.summary||'')}</p><div>${sanitizeTrustedHtml(x.body||'')}</div>${canReview?`<details class="handbook-review-editor"><summary>Foreslå rettelse eller ny viden</summary><form class="inline-handbook-review"><input type="hidden" name="sectionId" value="${esc(x.id)}"><input type="hidden" name="sectionTitle" value="${esc(x.title)}"><label>Type<select name="expertise"><option>Rav og sedimenttransport</option><option>Meteorologi</option><option>Oceanografi</option><option>Kystgeografi</option><option>Data og software</option><option>Andet</option></select></label><label>Hvad er forkert, uklart eller mangler?<textarea name="issue" required rows="4"></textarea></label><label>Foreslået formulering, mekanisme eller regelændring<textarea name="proposal" required rows="6"></textarea></label><label>Faglig begrundelse, observationer og kilder<textarea name="reasoning" required rows="5"></textarea></label><div class="two-col"><label>Navn<input name="expertName"></label><label>Organisation<input name="organization"></label></div><button class="admin-button" type="submit">Gem centralt</button><p class="form-status" role="status"></p></form></details>`:''}</section>`).join('')}</article><section id="handbookReviewQueue"><article class="admin-card"><div class="rule-card-head"><div><span class="eyebrow">Synlig arbejdsproces</span><h2>Reviewkø</h2><p>Her findes alle indsendte rettelser. Ejer kan vurdere, afvise eller implementere dem direkte i håndbogen.</p></div><div class="toolbar"><button class="admin-button secondary" id="refreshReviewQueue">Genindlæs</button><button class="admin-button danger" id="clearSystemReviews">Ryd systemtestposter</button></div></div>${reviewError?`<p class="status-bad">Reviewkøen kunne ikke hentes: ${esc(reviewError)}</p>`:''}</article><div class="admin-grid">${reviewCards}</div></section><section id="handbookLocalDrafts"><article class="admin-card"><div class="rule-card-head"><div><span class="eyebrow">Nødmekanisme</span><h2>Lokale nødkladder</h2><p>Disse findes kun i denne browser, indtil de er sendt til Supabase.</p></div>${localDrafts.length?'<button class="admin-button secondary" id="exportLocalDrafts">Eksportér nødkladder</button>':''}</div></article><div class="admin-grid">${localCards}</div></section>`;
  document.querySelector('#jumpReviewQueue').onclick=()=>document.querySelector('#handbookReviewQueue').scrollIntoView({behavior:'smooth'});
  document.querySelector('#jumpLocalDrafts').onclick=()=>document.querySelector('#handbookLocalDrafts').scrollIntoView({behavior:'smooth'});
  document.querySelector('#refreshReviewQueue').onclick=()=>renderHandbook();
  document.querySelector('#exportLocalDrafts')?.addEventListener('click',exportLocalHandbookDrafts);
  content.querySelectorAll('.inline-handbook-review').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),button=form.querySelector('button'),status=form.querySelector('.form-status');button.disabled=true;status.textContent='Gemmer og læser tilbage fra Supabase…';const result=await submitHandbookReview({handbookVersion:book.handbookVersion,sectionId:fd.get('sectionId'),sectionTitle:fd.get('sectionTitle'),expertise:fd.get('expertise'),issue:fd.get('issue'),proposal:fd.get('proposal'),reasoning:fd.get('reasoning'),expertName:fd.get('expertName'),organization:fd.get('organization')});if(result.central){status.innerHTML='Gemt centralt og verificeret. <button type="button" class="link-button open-review-after-save">Åbn reviewkøen</button>';form.reset();status.querySelector('.open-review-after-save').onclick=()=>renderHandbook();}else status.textContent=`Central gemning fejlede: ${result.error}. En lokal nødkladde er gemt og kan findes nederst på denne fane.`;button.disabled=false;});
  content.querySelectorAll('.archive-review').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-review-id]');if(!confirm('Slet denne post fra den normale reviewkø? Auditsporet bevares som soft-delete.'))return;button.disabled=true;try{await archiveHandbookReview(card.dataset.reviewId);await renderHandbook();}catch(error){alert(error.message);button.disabled=false;}});
  document.querySelector('#clearSystemReviews')?.addEventListener('click',async()=>{const rows=reviewRows.filter(x=>x.handbook_version==='systemtest'||x.section_id==='system-test'||/Automatisk systemtest/i.test(x.section_title||''));if(!rows.length){alert('Der er ingen synlige systemtestposter.');return;}if(!confirm(`Fjern ${rows.length} automatiske systemtestposter fra reviewkøen? Auditsporet bevares.`))return;for(const row of rows)await archiveHandbookReview(row.id,'Automatisk systemtest ryddet af ejer');await renderHandbook();});
  content.querySelectorAll('.save-review-status').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-review-id]'),status=card.querySelector('.review-status').value;button.disabled=true;try{await updateHandbookReview(card.dataset.reviewId,{status,resolution_note:`Status ændret af ejer ${new Date().toISOString()}`});await renderHandbook();}catch(error){alert(error.message);}finally{button.disabled=false;}});
  content.querySelectorAll('.implement-review').forEach(button=>button.onclick=()=>{const card=button.closest('[data-review-id]'),row=reviewRows.find(x=>x.id===card.dataset.reviewId),section=(book.sections||[]).find(x=>x.id===(row?.section_id||row?.client_payload?.sectionId));const panel=card.querySelector('.review-implementation'),textarea=panel.querySelector('.implementation-body');textarea.value=`${section?.body||''}\n\n<h4>Indarbejdet ekspertforslag</h4>\n<p>${esc(row?.proposal||'')}</p>`;panel.hidden=false;button.hidden=true;});
  content.querySelectorAll('.cancel-implementation').forEach(button=>button.onclick=()=>{const panel=button.closest('.review-implementation');panel.hidden=true;panel.closest('.handbook-review-card').querySelector('.implement-review').hidden=false;});
  content.querySelectorAll('.save-implementation').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-review-id]'),row=reviewRows.find(x=>x.id===card.dataset.reviewId),panel=button.closest('.review-implementation'),status=panel.querySelector('.form-status'),sectionId=row?.section_id||row?.client_payload?.sectionId,sections=structuredClone(book.sections||[]),index=sections.findIndex(x=>x.id===sectionId);if(index<0){status.textContent='Afsnittet findes ikke i den aktuelle håndbog.';return;}button.disabled=true;status.textContent='Renser indhold, gemmer central håndbog og verificerer readback…';try{sections[index].body=sanitizeTrustedHtml(panel.querySelector('.implementation-body').value);const nextVersion=`${book.handbookVersion||VERSION}-r${new Date().toISOString().slice(0,10).replaceAll('-','')}`;const updated={...book,sections,handbookVersion:nextVersion,updatedAt:new Date().toISOString(),lastReviewId:row.id};const saved=await saveAdminDocumentNow('handbook',updated);if(!saved.ok)throw saved.error;const readback=await loadAdminDocument('handbook',null);if(readback?.lastReviewId!==row.id)throw new Error('Håndbogsændringen kunne ikke verificeres efter gemning.');await updateHandbookReview(row.id,{status:'implemented',resolution_note:panel.querySelector('.implementation-note').value});await renderHandbook();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
  content.querySelectorAll('.retry-local-review').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-local-review-id]'),status=card.querySelector('.form-status');button.disabled=true;status.textContent='Sender og verificerer…';try{await retryLocalHandbookDraft(card.dataset.localReviewId);await renderHandbook();}catch(error){status.textContent=error.message;button.disabled=false;}});
  content.querySelectorAll('.delete-local-review').forEach(button=>button.onclick=()=>{if(!confirm('Slet denne lokale nødkladde permanent?'))return;deleteLocalHandbookDraft(button.closest('[data-local-review-id]').dataset.localReviewId);renderHandbook();});
 }catch(error){content.innerHTML=`<article class="admin-card status-banner warning"><h2>Håndbogen kunne ikke hentes</h2><p>${esc(error.message)}</p></article>`;}
}
async function renderDocumentation(){
 const documents=[['Håndbog','handbook','Den læsevenlige samlede forklaring'],['Gældende sandhed','current-truth','Det aktuelle styringsgrundlag'],['Implementeringsstatus','implementation-status','Hvad der er færdigt, delvist og planlagt'],['Aktive krav','active-requirements','Bindende krav til kommende arbejde'],['Kendte problemer','known-issues','Åbne og overvågede forhold'],['Masterlog','master-log','Versions- og beslutningshistorik']];
 content.innerHTML=`<article class="admin-card"><span class="eyebrow">Beskyttet projektviden</span><h2>Dokumentationscenter</h2><p>Åbn projektets styringsdokumenter direkte her. Dokumenterne vises kun efter adgangskontrollen til administrationen og kontrolleres mod deres versionsbundne kildehash.</p></article><div class="admin-grid">${documents.map(([title,id,description])=>`<article class="admin-card"><h3>${esc(title)}</h3><p>${esc(description)}</p><button class="admin-button open-doc" data-doc-id="${esc(id)}">Åbn</button></article>`).join('')}</div><article id="documentationViewer" class="admin-card" hidden><div class="rule-card-head"><h2 id="documentationViewerTitle"></h2><button class="admin-button secondary" id="closeDocumentationViewer">Luk</button></div><pre id="documentationViewerBody" class="documentation-pre"></pre></article>`;
 content.querySelectorAll('.open-doc').forEach(button=>button.onclick=async()=>{if(button.dataset.docId==='handbook'){state.tab='handbook';document.querySelectorAll('.admin-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='handbook'));render();return;}const viewer=document.querySelector('#documentationViewer'),body=document.querySelector('#documentationViewerBody');viewer.hidden=false;document.querySelector('#documentationViewerTitle').textContent=button.closest('.admin-card').querySelector('h3').textContent;body.textContent='Henter og verificerer dokument…';try{const bundle=await loadAdminDocument('rdks-documentation-center',null);if(bundle?.schemaVersion!==1||bundle?.sourceVersion!==VERSION||!Array.isArray(bundle?.documents))throw new Error('den beskyttede dokumentpakke har forkert version eller format');const documentEntry=bundle.documents.find(entry=>entry?.id===button.dataset.docId);if(!documentEntry?.content||!documentEntry?.sha256)throw new Error('dokumentet mangler i den beskyttede pakke');if(await sha256Text(documentEntry.content)!==documentEntry.sha256)throw new Error('dokumentets kildehash matcher ikke');body.textContent=documentEntry.content;}catch(error){body.textContent=`Dokumentet kunne ikke verificeres: ${error.message}`;}viewer.scrollIntoView({behavior:'smooth'});});
 document.querySelector('#closeDocumentationViewer').onclick=()=>document.querySelector('#documentationViewer').hidden=true;
}
function renderSystem(){
 const active=activePublicRavScoreState();
 const modelCard=active.ok
  ? `<article class="admin-card"><h2>Offentlig RavScore-model</h2><div class="metric">20/50/30</div><p class="muted">${esc(active.value.labelDa)} · ${esc(active.value.binding.modelId)} · state ${esc(active.value.binding.stateSchemaVersion)}</p><p class="hint">${esc(active.value.statusDa)} Ingen administratorregler, offentlig shadowmodel eller krydsmodel-fallback.</p></article>`
  : activeModelUnavailableCard(active);
 content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Version</h2><div class="metric">${VERSION}</div></article>${modelCard}</div><article class="admin-card"><h2>Vedligeholdelse</h2><div class="toolbar">${active.ok?'<button id="exportDiag" class="admin-button secondary">Eksportér diagnostik</button>':''}<button id="clearCaches" class="admin-button danger">Ryd RavRadar-caches</button><button id="logoutAdmin" class="admin-button secondary">Log ud</button></div><p class="hint">Cacheknappen rydder kun caches, hvis navn starter med “ravradar”. Den sletter ikke observationer eller ture. Diagnostik kan kun eksporteres, når den aktive offentlige modelbinding er verificeret.</p></article><article class="admin-card"><h2>Sådan ændres RavScore</h2><p>Ekspertviden indsendes gennem håndbogens review. En scoreændring bliver først offentlig, når den er omsat til én samlet model, bundet til ny model- og stateversion, dokumenteret i RDKS, testet og udgivet atomisk i en ny version.</p></article>`;
 document.querySelector('#exportDiag')?.addEventListener('click',()=>{
  const publicWaterLevelZones=Object.fromEntries(Object.entries(state.conditions.zones||{}).map(([zoneId,z])=>[zoneId,{zoneName:state.zones.find(f=>f.properties?.id===zoneId)?.properties?.name||zoneId,provider:z.provider??null,currentWaterLevelCm:z.current?.waterLevelCm??null,forecastProvider:z.forecast?.provider??null,forecastValidUntil:z.forecast?.validUntil??null}]));
  download('ravradar-diagnostik.json',{version:VERSION,exportedAt:new Date().toISOString(),publicDatasetGeneratedAt:state.conditions.generatedAt??null,health:state.health,protectedRuntimeSummary:{generatedAt:state.runtime?.generatedAt??null,version:state.runtime?.version??null,componentCoverage:state.runtime?.componentCoverage??null,acquisition:state.runtimeDetails?.acquisition??null,dataQuality:state.runtimeDetails?.dataQuality??null},publicWeatherZoneCount:Object.keys(state.conditions.zones||{}).length,zoneCount:state.zoneRegistry.counts.registered,activeZoneCount:state.zoneRegistry.counts.active,legacyZoneCount:state.zoneRegistry.counts.legacy,scoreProfile:active.value.diagnosticScoreProfile,publicWaterLevelOverview:{description:'Dataminimeret overblik fra den offentlige startpakke. Beskyttede kilde- og driftsdetaljer indgår ikke som offentlige filer.',zones:publicWaterLevelZones}});
 });
 document.querySelector('#clearCaches').onclick=async()=>{if(!confirm('Ryd RavRadars app-caches?'))return;for(const name of await caches.keys())if(name.toLowerCase().startsWith('ravradar'))await caches.delete(name);alert('RavRadar-caches er ryddet.');};
 document.querySelector('#logoutAdmin').onclick=async()=>{await signOut();location.replace('./')};
}


function defaultVisitorPeriod(){const to=new Date(),from=new Date(to);from.setDate(from.getDate()-29);return {from:from.toISOString().slice(0,10),to:to.toISOString().slice(0,10)};}
function renderVisitors(){
 const period=defaultVisitorPeriod();
 content.innerHTML=`<article class="admin-card"><div class="section-head"><div><h2>Privat besøgsstatistik</h2><p class="muted">Kun samlede dagstal. Ingen IP-adresser, præcis placering, browserfingeraftryk eller personprofiler.</p></div></div><form id="visitorPeriod" class="toolbar"><label>Fra <input type="date" name="from" value="${period.from}" required></label><label>Til <input type="date" name="to" value="${period.to}" required></label><button class="admin-button">Vis periode</button></form></article><div id="visitorReport"><article class="admin-card"><p>Henter besøgstal…</p></article></div>`;
 const form=document.querySelector('#visitorPeriod');
 const load=async()=>{const box=document.querySelector('#visitorReport');box.innerHTML='<article class="admin-card"><p>Henter besøgstal…</p></article>';try{const report=await loadVisitorReport(form.elements.from.value,form.elements.to.value);const rows=(report.days||[]).map(row=>`<tr><td>${new Date(`${row.day}T12:00:00`).toLocaleDateString('da-DK')}</td><td>${Number(row.pageViews).toLocaleString('da-DK')}</td><td>${Number(row.browserVisits).toLocaleString('da-DK')}</td></tr>`).join('');box.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Sidevisninger</h2><div class="metric">${Number(report.pageViews||0).toLocaleString('da-DK')}</div><p class="muted">Alle indlæsninger i perioden</p></article><article class="admin-card"><h2>Browserbesøg</h2><div class="metric">${Number(report.browserVisits||0).toLocaleString('da-DK')}</div><p class="muted">Første åbning pr. browserfane og dag – ikke unikke personer</p></article><article class="admin-card"><h2>Oprettede login</h2><div class="metric">${Number(report.registeredAccounts||0).toLocaleString('da-DK')}</div><p class="muted">${Number(report.activeAccounts||0).toLocaleString('da-DK')} aktive konti</p></article></div><article class="admin-card"><h2>Dag for dag</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Dato</th><th>Sidevisninger</th><th>Browserbesøg</th></tr></thead><tbody>${rows||'<tr><td colspan="3">Ingen registrerede besøg i perioden.</td></tr>'}</tbody></table></div></article>`;}catch(error){box.innerHTML=`<article class="admin-card"><p class="status-bad"><b>Besøgstallene kunne ikke hentes.</b></p><p>${esc(error.message)}</p><p class="hint">RavRadar virker fortsat normalt. Kontrollér at databasemigreringen til 4.0.310 er installeret.</p></article>`;}};
 form.addEventListener('submit',event=>{event.preventDefault();load();});load();
}

function renderHistory(){
 const active=activePublicRavScoreState();
 if(!active.ok){content.innerHTML=activeModelUnavailableCard(active,{title:'Historisk analyse blokeret'});return;}
 const zones=state.zones.map(z=>z.properties).sort((a,b)=>(a.name||'').localeCompare(b.name||'','da'));
 const eligibilityText=active.value.observationCalibrationEligible
  ? `Kun komplette ture, der er bundet til ${esc(active.value.labelDa)} og et uforanderligt prognosesnapshot, indgår i fundrate og gennemsnit.`
  : `${esc(active.value.labelDa)} er ikke kalibreringsegnet. Turene bevares som historik, men indgår ikke i fundrate eller modelgennemsnit.`;
 content.innerHTML=`<article class="admin-card"><h2>Historisk analyse</h2><p class="muted">${eligibilityText} Ældre og manuelle ture bevares uden at blive blandet ind i modelmålingerne.</p><div class="toolbar"><input id="historyDate" type="date"><select id="historyZone"><option value="">Alle zoner</option>${zones.map(z=>`<option value="${esc(z.id)}">${esc(z.name)}</option>`).join('')}</select><select id="historyResult"><option value="">Alle resultater</option><option value="none">Intet fund</option><option value="small">Små stykker</option><option value="medium">Noget rav</option><option value="good">Godt fund</option></select><button id="clearHistory" class="admin-button secondary">Ryd filtre</button></div></article><div id="historyOutput"></div>`;
 const draw=()=>{const summary=historicalSummary({date:document.querySelector('#historyDate').value||null,zoneId:document.querySelector('#historyZone').value||null,result:document.querySelector('#historyResult').value||null},active.value.binding,{allowCalibration:active.value.observationCalibrationEligible}),visibleRows=summary.allRows.map(row=>activeAdminObservationDto(row,active.value)),bindingLabel=status=>({'current-eligible':'Aktuel model · analyseegnet','current-ineligible':'Aktuel model · ikke analyseegnet','historical-model-bound':'Tidligere model · kun historik',unbound:'Uden modelbinding · kun historik'})[status]||'Kun historik';document.querySelector('#historyOutput').innerHTML=`<div class="admin-grid"><article class="admin-card"><h3>Modelbundne ture</h3><div class="metric">${summary.count}</div><p class="muted">${summary.excludedCount} øvrige ture er bevaret uden for beregningen</p></article><article class="admin-card"><h3>Fund</h3><div class="metric">${summary.finds}</div></article><article class="admin-card"><h3>Fundrate</h3><div class="metric">${summary.successRate==null?'–':Math.round(summary.successRate*100)+'%'}</div></article><article class="admin-card"><h3>Gns. RavScore</h3><div class="metric">${summary.averages.ravScore??'–'}</div></article></div><article class="admin-card admin-table-wrap"><table class="admin-table"><thead><tr><th>Dato</th><th>Zone</th><th>Resultat</th><th>RavScore</th><th>Vandstand</th><th>Vind</th><th>Bølger</th><th>Modelbinding</th></tr></thead><tbody>${visibleRows.map(r=>`<tr><td>${esc(String(r.observed_at||'').slice(0,10))}</td><td>${esc(r.zone_name||r.actual_zone_id||'–')}</td><td>${esc(r.result||'–')}</td><td>${esc(r.rav_score??'–')}</td><td>${esc(r.water_level_cm??'–')} cm</td><td>${esc(r.wind_speed_mps??'–')} m/s</td><td>${esc(r.wave_height_m??'–')} m</td><td>${esc(bindingLabel(r.calibration_binding_status))}</td></tr>`).join('')||'<tr><td colspan="8">Ingen ture matcher filtrene.</td></tr>'}</tbody></table></article>`};
 ['historyDate','historyZone','historyResult'].forEach(id=>document.querySelector('#'+id).onchange=draw);document.querySelector('#clearHistory').onclick=()=>{document.querySelector('#historyDate').value='';document.querySelector('#historyZone').value='';document.querySelector('#historyResult').value='';draw()};draw();
}
function renderLearning(){
 const analysis=analyzeObservations();
 const active=activePublicRavScoreState();
 if(!active.ok){content.innerHTML=activeModelUnavailableCard(active,{title:'Kalibreringsgrundlag blokeret'});return;}
 const effortShare=analysis.sampleSize?Math.round((analysis.effortCount/analysis.sampleSize)*100):0;
 const snapshotShare=analysis.sampleSize?Math.round((analysis.snapshotLinkCount/analysis.sampleSize)*100):0;
 const calibrationNotice=active.value.observationCalibrationEligible
  ? 'Datagrundlaget kan først indgå efter den særskilte repræsentativitets- og valideringsgate.'
  : 'Den aktive offentlige modeltilstand er udtrykkeligt ikke kalibreringsegnet.';
 content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Registrerede ture</h2><div class="metric">${analysis.sampleSize||0}</div><p class="muted">Kun dækningskontrol</p></article><article class="admin-card"><h2>Dækkede zoner</h2><div class="metric">${analysis.zoneCount||0}</div><p class="muted">Geografisk spredning skal vurderes før kalibrering</p></article><article class="admin-card"><h2>Reelle nul-fund</h2><div class="metric">${analysis.noFindCount||0}</div><p class="muted">Tæller kun sammen med dokumenteret søgeindsats</p></article></div><article class="admin-card"><h2>Kan data bruges til scorekalibrering?</h2><p><strong>Ikke endnu.</strong> Aktiv offentlig model: ${esc(active.value.labelDa)}. Denne side ændrer ikke modellen, den offentlige RavScore eller nogen lokal model. ${esc(calibrationNotice)}</p><ul><li>${effortShare}% af turene har registreret søgetid.</li><li>${snapshotShare}% har et uforanderligt link til det gemte vejrbillede.</li><li>${analysis.modes?.beach||0} strandture og ${analysis.modes?.waders||0} wadersture indgår.</li></ul><p class="hint">En senere scoreændring kræver repræsentative ture, reelle nul-fund, tidsmæssig test, geografisk hold-out, en eksplicit RDKS-beslutning, kildekodeændring, målrettede tests og offentlig produktionskontrol. Den kan ikke vedtages eller aktiveres på denne side.</p></article>`;
}

const saveBadge=document.createElement('div');
saveBadge.className='admin-save-status';
saveBadge.textContent=centralAdminStorageEnabled()?'Supabase tilsluttet · central lagring klar':'Kun lokal kladde – Supabase-login mangler';
document.body.appendChild(saveBadge);
onAdminSaveStatus(status=>{
  saveBadge.className=`admin-save-status ${status.state}`;
  saveBadge.textContent=status.state==='saving'?'Gemmer…':status.state==='saved'?`Gemt centralt ${status.at?new Date(status.at).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'}):''}`:`Kun lokal kladde${status.error?' · '+status.error:''}`;
});
window.addEventListener('beforeunload',e=>{if(saveBadge.classList.contains('saving')){e.preventDefault();e.returnValue='';}});

boot();
